CREATE TABLE IF NOT EXISTS notifications (id CHAR(36) PRIMARY KEY,seller_id CHAR(36) NOT NULL,type ENUM('PRODUCT_APPROVED','PRODUCT_REJECTED','SHOP_APPROVED','SHOP_REJECTED') NOT NULL,title VARCHAR(160) NOT NULL,message TEXT NOT NULL,reference_id CHAR(36) NULL,read_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT notifications_seller_fk FOREIGN KEY(seller_id) REFERENCES sellers(id) ON DELETE CASCADE,UNIQUE KEY notification_once (seller_id,type,reference_id),INDEX notifications_seller_idx(seller_id,created_at));
